import { Component, inject, OnInit, signal } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { PID_PATTERN, UserSessionService } from '../../services/user-session.service';

/**
 * Entry point. Participants arrive via a link like  https://<host>/?pid=<id>
 * (generated by Qualtrics). Without a valid pid the study cannot start,
 * so that no data is recorded without a participant ID.
 */
@Component({
  selector: 'app-start',
  standalone: true,
  templateUrl: './start.component.html',
  styleUrl: '../thank-you/thank-you.component.scss',
})
export class StartComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private session = inject(UserSessionService);

  missingPid = signal(false);

  ngOnInit() {
    const pid = this.route.snapshot.queryParamMap.get('pid')?.trim();
    if (pid && PID_PATTERN.test(pid)) {
      this.session.setPid(pid);
      this.router.navigate(['/feed'], { replaceUrl: true });
    } else if (this.session.hasPid()) {
      this.router.navigate(['/feed'], { replaceUrl: true });
    } else {
      this.missingPid.set(true);
    }
  }
}
